INSERT INTO course_catalog
    (id, uuid, tenant_id, organization_id, course_code, category_id, primary_instructor_id, title, subtitle, summary, description, learning_objectives_json, target_audience_json, prerequisites_json, difficulty_level, language_code, cover_resource_snapshot, tags_json, estimated_duration_seconds, lesson_count_snapshot, student_count_snapshot, rating_score_snapshot, rating_count_snapshot, external_source_id, price_amount, original_price_amount, currency, is_free, is_collection, course_kind, author_user_id, author_display_name, review_round, visibility, publish_status, published_at, status, created_at, created_by, updated_at, updated_by, version)
VALUES
    ('course-bili-bv12b411l7ns', 'course-bili-bv12b411l7ns', '100001', '0', 'BILI-LANG-013', 'course-category-language', 'instructor-bili-31537090', '超级棒的粤语教程', '60 讲完整课程 · 15 小时 19 分钟', '尽量不要收藏，免得被和谐 本视频仅供学习 禁止商用 侵删致歉 随着广东地区经济的飞速发展，很多人都到广州，香港去发展，面临的问题就是如何与那里的人沟通。虽然现今大多数广东', '尽量不要收藏，免得被和谐 本视频仅供学习 禁止商用 侵删致歉 随着广东地区经济的飞速发展，很多人都到广州，香港去发展，面临的问题就是如何与那里的人沟通。虽然现今大多数广东人听得懂普通话，但在很多时候仍然使用粤语来进行交流，因此学习粤语有时候也是必要的。尤其在香港，他们的语言长久以来都是粤语和英语为主流，形成了他们独特的文化，作为东亚地区的经济金融中心，粤语也有相当广泛深远的影响。因此如果掌握了粤语这门特殊的地方语言以后，还是有着相当大的优势的。课程结构：共 8 章 60 讲，累计时长 15 小时 19 分钟，视频画面与课程封面同源。学习方式：按章节顺序观看即可，每讲均可在课程播放器中直接播放 B 站官方视频。', '["建立标准发音与基础语法体系","掌握高频场景下的听说读写实战表达","形成可持续的每日学习与复习节奏","具备考试或职场语言应用所需的能力"]', '["零基础或基础薄弱的语言学习者","备考雅思托福四六级的在校生","需要职场外语能力的从业者"]', '["每天可投入 30 分钟以上练习时间","自备耳机与可录音的设备"]', 'beginner', 'zh-CN', 'https://i0.hdslb.com/bfs/archive/69af8267e07c1a8bb6910b1106887b54c4bd0db3.png', '["语言学习","口语训练","考试备考","超级棒的粤语教程"]', 55181, 60, 1294949, '4.5', 393131, 'BV12b411L7NS', NULL, NULL, NULL, 1, 0, 'standard', NULL, '大鱼大鱼不是鱼', 0, 'tenant', 'published', '2019-04-14T12:46:52.000Z', 'active', CURRENT_TIMESTAMP::text, 'catalog-seed', CURRENT_TIMESTAMP::text, 'catalog-seed', 0)
