INSERT INTO course_catalog
    (id, uuid, tenant_id, organization_id, course_code, category_id, primary_instructor_id, title, subtitle, summary, description, learning_objectives_json, target_audience_json, prerequisites_json, difficulty_level, language_code, cover_resource_snapshot, tags_json, estimated_duration_seconds, lesson_count_snapshot, student_count_snapshot, rating_score_snapshot, rating_count_snapshot, external_source_id, price_amount, original_price_amount, currency, is_free, is_collection, course_kind, author_user_id, author_display_name, review_round, visibility, publish_status, published_at, status, created_at, created_by, updated_at, updated_by, version)
VALUES
    ('course-bili-bv1vapmzmejz', 'course-bili-bv1vapmzmejz', '100001', '0', 'BILI-LANG-079', 'course-category-language', 'instructor-bili-1586658', '翔翔的俄语课：零基础七年级上册逐页过 | 零基础俄语入门 | 俄语发音系统讲解 | 七年级俄语（上册）| 中学俄语 | 高考俄语 | 俄语学习', '14 讲完整课程 · 4 小时 7 分钟', '我还有两个月就毕业了。在毕业之前，我准备做一次“收尾工作”：那就是把我一直未完结的俄语课做个“了断”。从三月开始，我会把之前没有更新完的《大学俄语1》更新完，《俄语初级下》会在3月跟大家见面。', '课程简介：大家好，我还有两个月就毕业了。在毕业之前，我准备做一次“收尾工作”：那就是把我一直未完结的俄语课做个“了断”。从三月开始，我会把之前没有更新完的《大学俄语1》更新完，《俄语初级下》会在3月跟大家见面。我又重新录了一套最最最新版本的中学俄语，也就是2024刚刚出版的这套初中俄语，（目前只出到八年级上），趁着开学季放出来和大家见面。这部分是《七年级上册》，虽然写着七年级上册，其实是整个俄语的语音课。希望真正帮助零基础的同学，从发音开始，把基础打牢。我对每页都做了详细讲解，方便大家从零开始学习。这套内容本身就足够帮助你完成俄语入门。如果你只是想了解俄语、打好发音基础，跟着这一套学就完全可以。如果你希望系统地继续往下学习，包括语法体系、课文精讲、练习讲解和更完整的大学俄语课程结构，也可以了解我”课堂“里的《大学俄语》付费课程。那部分内容更系统，适合打算长期学习俄语的同学。如果这套免费课程对你有帮助，也欢迎支持一下我的系统课程，让我能继续把俄语讲下去。课程结构：共 2 章 14 讲，累计时长 4 小时 7 分钟，视频画面与课程封面同源。学习方式：按章节顺序观看即可，每讲均可在课程播放器中直接播放 B 站官方视频。', '["建立标准发音与基础语法体系","掌握高频场景下的听说读写实战表达","形成可持续的每日学习与复习节奏","具备考试或职场语言应用所需的能力"]', '["零基础或基础薄弱的语言学习者","备考雅思托福四六级的在校生","需要职场外语能力的从业者"]', '["每天可投入 30 分钟以上练习时间","自备耳机与可录音的设备"]', 'beginner', 'zh-CN', 'https://i2.hdslb.com/bfs/archive/fca87ab9409ceccf43ab01c10223411a620cc6a8.jpg', '["语言学习","口语训练","考试备考","已完结","翔翔的俄语课","零基础七年级上册逐页过"]', 14823, 14, 8052, '4.6', 1184, 'BV1VaPMzMEJz', NULL, NULL, NULL, 1, 0, 'standard', NULL, '翔翔的学习频道', 0, 'tenant', 'published', '2026-03-01T09:15:13.000Z', 'active', CURRENT_TIMESTAMP::text, 'catalog-seed', CURRENT_TIMESTAMP::text, 'catalog-seed', 0)
